static Vec3 rt_rotate(Vec3 p,Vec3 pivot,Vec3 axis,double deg){double n=std::sqrt(axis.x*axis.x+axis.y*axis.y+axis.z*axis.z);if(n<1e-12)return p;axis={axis.x/n,axis.y/n,axis.z/n};p={p.x-pivot.x,p.y-pivot.y,p.z-pivot.z};constexpr double pi=3.14159265358979323846;double r=deg*pi/180.0,co=std::cos(r),si=std::sin(r);Vec3 cr{axis.y*p.z-axis.z*p.y,axis.z*p.x-axis.x*p.z,axis.x*p.y-axis.y*p.x};double d=axis.x*p.x+axis.y*p.y+axis.z*p.z;return {p.x*co+cr.x*si+axis.x*d*(1-co)+pivot.x,p.y*co+cr.y*si+axis.y*d*(1-co)+pivot.y,p.z*co+cr.z*si+axis.z*d*(1-co)+pivot.z};}
static Vec3 rt_transform_node(Vec3 p,const std::string&name,const std::vector<MachineNode>&nodes,const MachineState&s,bool inverse){
 auto it=std::find_if(nodes.begin(),nodes.end(),[&](const MachineNode&n){return n.name==name;});if(it==nodes.end())return p;
 std::vector<const MachineNode*> chain;std::string parent=it->parent;int guard=0;while(!parent.empty()&&guard++<64){auto pi=std::find_if(nodes.begin(),nodes.end(),[&](const MachineNode&n){return n.name==parent;});if(pi==nodes.end())break;chain.push_back(&*pi);parent=pi->parent;}
 auto apply=[&](const MachineNode&n,double sign){if(n.type==MachineNodeType::LinearAxis){double q=n.name=="X"?s.X:n.name=="Y"?s.Y:n.name=="Z"?s.Z:0;double m=std::sqrt(n.axis.x*n.axis.x+n.axis.y*n.axis.y+n.axis.z*n.axis.z);if(m>1e-12){p.x+=sign*n.axis.x/m*q;p.y+=sign*n.axis.y/m*q;p.z+=sign*n.axis.z/m*q;}}else if(n.type==MachineNodeType::RotaryAxis){double q=n.name=="A"?s.A:n.name=="C"?s.C:0;p=rt_rotate(p,n.pivot,n.axis,sign*q);}};
 if(inverse){for(const auto*n:chain)apply(*n,-1.0);}else{for(auto it2=chain.rbegin();it2!=chain.rend();++it2)apply(**it2,1.0);}return p;}
void Runtime::configure_machine_transforms(const std::vector<MachineNode>& nodes){machine_nodes_=nodes;collisions_.set_machine_transformers([this](const std::string&name,const Vec3&p){return rt_transform_node(p,name,machine_nodes_,state_,false);},[this](const std::string&name,const Vec3&p){return rt_transform_node(p,name,machine_nodes_,state_,true);});}
static int code(const Word&w){return static_cast<int>(std::llround(w.value));}
