bool Runtime::save_machine_config(const std::string& path,std::string&e) const{
 std::ofstream f(path);if(!f){e="cannot write machine config";return false;}
 f<<"{\n  \"machine\": {\n    \"name\": \""<<json_escape(machine_name_)<<"\",\n    \"nodes\": [\n";
 for(size_t i=0;i<machine_nodes_.size();++i){const auto&n=machine_nodes_[i];const char*t=n.type==MachineNodeType::LinearAxis?"linear":n.type==MachineNodeType::RotaryAxis?"rotary":n.type==MachineNodeType::Tool?"tool":n.type==MachineNodeType::Holder?"holder":"fixture";
  f<<"      {\"name\": \""<<json_escape(n.name)<<"\", \"type\": \""<<t<<"\", \"parent\": "<<(n.parent.empty()?"null":"\""+json_escape(n.parent)+"\"")<<", \"axis\": ["<<n.axis.x<<", "<<n.axis.y<<", "<<n.axis.z<<"], \"pivot\": ["<<n.pivot.x<<", "<<n.pivot.y<<", "<<n.pivot.z<<"], \"limit\": {\"min\": "<<n.min<<", \"max\": "<<n.max<<", \"wrap\": "<<(n.wrap?"true":"false")<<"}, \"mesh\": \""<<json_escape(n.mesh)<<"\", \"collision\": "<<(n.collision_enabled?"true":"false")<<"}"<<(i+1<machine_nodes_.size()?",":"")<<"\n";
 }
 f<<"    ]\n  }\n}\n";return true;
}
bool Runtime::update_machine_node(const MachineNode& n,std::string&e){
 auto it=std::find_if(machine_nodes_.begin(),machine_nodes_.end(),[&](const MachineNode&x){return x.name==n.name;});if(it==machine_nodes_.end()){e="machine node not found";return false;}*it=n;MachineConfig probe; // validate through the same tree rules by reloading is intentionally deferred to saved JSON.
 if((n.type==MachineNodeType::LinearAxis||n.type==MachineNodeType::RotaryAxis)&&std::sqrt(n.axis.x*n.axis.x+n.axis.y*n.axis.y+n.axis.z*n.axis.z)<1e-12){e="machine node axis is zero";return false;}if(n.parent==n.name){e="machine node cannot parent itself";return false;}configure_machine_transforms(machine_nodes_);return true;
}
bool Runtime::add_machine_node(const MachineNode& n,std::string&e){if(n.name.empty()){e="machine node name is empty";return false;}if(std::find_if(machine_nodes_.begin(),machine_nodes_.end(),[&](const MachineNode&x){return x.name==n.name;})!=machine_nodes_.end()){e="machine node already exists";return false;}machine_nodes_.push_back(n);if(!n.parent.empty()&&std::find_if(machine_nodes_.begin(),machine_nodes_.end(),[&](const MachineNode&x){return x.name==n.parent;})==machine_nodes_.end()){e="parent node not found";machine_nodes_.pop_back();return false;}configure_machine_transforms(machine_nodes_);return true;}
bool Runtime::remove_machine_node(const std::string& name,std::string&e){auto it=std::find_if(machine_nodes_.begin(),machine_nodes_.end(),[&](const MachineNode&x){return x.name==name;});if(it==machine_nodes_.end()){e="machine node not found";return false;}for(const auto&x:machine_nodes_)if(x.parent==name){e="cannot remove node with children";return false;}machine_nodes_.erase(it);configure_machine_transforms(machine_nodes_);return true;}
void Runtime::reset(){state_={};modal_={};feed_=rpm_=0;tool_=d_=0;last_motion_.clear();feed_hold_=false;alarm_.clear();collisions_.clear();}
